/* ------------------------------------------------------------- examples */

const podcastTurns = PODCAST_TURNS.map((turn, index) => ({
    ...turn,
    start: index === 0 ? 0 : PODCAST_TURNS[index - 1].end,
    speakerName: PODCAST_SPEAKERS[turn.speaker],
}));

// The bulletin, anchored on the one segment that was measured: the first
// headline runs 4.987s → 10.5s. The sign-on before it and the rest after it
// are paced inside the two remaining stretches.
const newsBlocks = (() => {
    const [headStart, headEnd] = NEWS_HEADLINE_SPAN;
    const before = NEWS_PARAS.slice(0, NEWS_HEADLINE_INDEX);
    const after = NEWS_PARAS.slice(NEWS_HEADLINE_INDEX + 1);

    return [
        ...distribute(before, 0, headStart).map((span, i) => ({ ...span, text: before[i] })),
        { start: headStart, end: headEnd, text: NEWS_PARAS[NEWS_HEADLINE_INDEX], kind: 'headline' },
        ...distribute(after, headEnd, CLIP_LENGTHS.news).map((span, i) => ({
            ...span,
            text: after[i],
        })),
    ];
})();

// Long reads: opening and closing sit on measured marks, the body is paced
// between them.
const longRead = (opening, body, closing, anchors, duration) => [
    { start: 0, end: anchors.openEnd, text: opening, kind: 'opening' },
    ...distribute(body, anchors.openEnd, anchors.closeStart).map((span, i) => ({
        ...span,
        text: body[i],
    })),
    { start: anchors.closeStart, end: duration, text: closing, kind: 'closing' },
];

